    const startLine = this.line;
    const startCol = this.column;

    const twoChar = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>'];

    const char = this.peek();
    const char2 = char + (this.peek(1) || '');

    if (twoChar.includes(char2)) {
      this.advance();
      this.advance();
      this.tokens.push({
        line: startLine,
        column: startCol,
        kind: 'punct',
        body: char2,
      });
      return;
    }

    const oneChar = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'];

    if (oneChar.includes(char)) {
      this.advance();
      this.tokens.push({
        line: startLine,
        column: startCol,
        kind: 'punct',
        body: char,
      });
      return;
    }

    // Should not reach here
    this.advance();
  }

  scan() {
    while (this.pos < this.source.length && !this.error) {
      this.skipWhitespace();
      if (this.pos >= this.source.length || this.error) break;

      // Check for comments
      if (this.peek() === '/' && this.peek(1) === '/') {
        this.skipLineComment();
        continue;
      }

      if (this.peek() === '/' && this.peek(1) === '*') {
        this.skipBlockComment();
        if (this.error) break;
        continue;
      }

      // Check for tokens
      const char = this.peek();

      if (/[a-zA-Z_]/.test(char)) {
        this.scanIdentifierOrKeyword();
      } else if (/[0-9]/.test(char)) {
        this.scanNumber();
        if (this.error) break;
      } else if (char === '"') {
        this.scanString();
        if (this.error) break;
      } else if (char === 'r' && this.peek(1) === '"') {
        this.scanRawString();
        if (this.error) break;
      } else if (['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'].includes(char)) {
        this.scanPunctuation();
      } else {
        // Unexpected character
        const line = this.line;
        const col = this.column;
        this.setError(line, col, `unexpected character ${char}`);
        break;
      }
    }

    return {
      tokens: this.tokens,
      error: this.error,
    };
  }
}
